// now is the package clock, overridable in tests for deterministic _stages and
// _provenance timestamps. Production uses time.Now.
var now = time.Now

// metadataResolver obtains the typed MetadataSource client for a source's
// capability binding. Enrich supplies the production resolver
// (plugin.Manager.MetadataSource); the in-package test injects one returning a
// fake sdk.MetadataSource (R8 — the interface's second implementation). It is an
// unexported test seam, mirroring scan.scannerResolver, and does not count toward
// the exported-symbol budget.
type metadataResolver func(pluginID, capabilityID string) (sdk.MetadataSource, error)

// Deps are the collaborators Enrich orchestrates. Store and Modules are carried
// for API fidelity (the composition root wires them; Phase B persistence/retry
// uses Store). Phase A resolves metadata_source clients via Plugins only.
// PackItem is the streams lane's packaging seam (packaged-playback D-10): a
// nil PackItem disables the lane. It is wired flat in cmd/mellifera to the
// stream package's pack lane — enrich stays ignorant of stream (Interface 2).
type Deps struct {
	Store   *store.Store
	Plugins *plugin.Manager
	Modules *module.Registry
	// PackItem packages one item's original file (absPath) into fMP4-HLS and
	// returns the published build pointer. ffprobe carries the stored verbatim
	// facts (the lane reads them only for this call). voiceovers are the
	// episode-linked audio sidecar files' absolute paths in document order
	// (serial-watch-flow D-2), extracted from the document and derived from the
	// episode's own stored facts by documentVoiceoverPaths — never a client
	// path. An error is a terminal packaging failure: the lane records a
	// pack_failed ledger row under __streams__ and persists the failed state —
	// metadata completion is never touched either way.
	PackItem func(ctx context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (PackOutcome, error)
	// FetchGate spaces each plugin's outbound fetches at least its
	// min_interval_ms apart (enrichment D-5: pacing is contract conformance
	// the core enforces server-side). Wired flat in cmd/mellifera beside
	// PackItem (enrich.NewFetchGate); nil (sync runs, in-package tests) means
	// unpaced.
	FetchGate *FetchGate
}

// Result is the outcome of enriching one item: how many sources were attempted,
// how many advanced the item, and the per-source soft-fail warnings.
type Result struct {
	Stages    int
	Succeeded int
	Warnings  []string
}

// Enrich runs the configured metadata_source chain for ONE item in module
// Priority order (serial within the item — D8; no hybrid/parallel — D14),
// mutating the document (sources/_provenance/_view/_stages) and returning the
// advanced lifecycle status. Soft failures (a source RPC error, a namespace
// violation, an unloaded source) are recorded in Result.Warnings and the item
// still advances to the furthest state its successful stages justify (AC-6).
// A cancelled context is the only hard failure (B8): it returns status=failed
// with a _error record and the cause.
//
// In the async substrate (Phase B1) this is the SYNC per-item entry, now
// worker-internal: the async Queue's per-item driver reuses the same factored
// helpers (enrichDoc, runSource/runSourceRetryable, applyContribution,
// orderedSources, nextState) but adds per-source retry + the ledger. Enrich is
// preserved (deprecate-don't-delete, AC-3) for sync use and tests — its
// original five-argument behavior is unchanged.
//
// extraPlugins (element-pages D-4) are the item's element-attached plugin ids
// (the item_parsers attachment order). They run AFTER the chain, in attachment
// order, through the identical runSource path — the standard
// namespace/_provenance/_stages writes; element attachment changes WHO runs,
// not how a source writes. A CLIENT-locked extra is honored here (the sync
// Mode-B run is allowed what the async queue excludes under D-Q1).
func Enrich(ctx context.Context, deps Deps, mod module.Module, doc map[string]any, base *scannerv1.IdentifyResult, extraPlugins ...string) (map[string]any, string, Result, error) {
	return enrichDoc(ctx, deps.Plugins.MetadataSource, mod, doc, base, runExtras(mod, extraPlugins))
}

// enrichDoc is the orchestrator body, factored out so the test can inject a fake
// metadata resolver (the production *plugin.Manager cannot be faked from outside
// the plugin package — mirror of scan.runScan/scannerResolver). extras are the
// resolved element-attached bindings (runExtras), run after the chain in
// attachment order through the same per-source path.
func enrichDoc(ctx context.Context, resolve metadataResolver, mod module.Module, doc map[string]any, base *scannerv1.IdentifyResult, extras []module.MetadataSourceBinding) (map[string]any, string, Result, error) {
	res := Result{}
	if doc == nil {
		doc = map[string]any{}
	}
	if err := ctx.Err(); err != nil {
		return doc, statusFailed, res, hardError(doc, err)
	}
	status := statusNew
	begun := false
	succeeded, failed := 0, 0
	for _, src := range append(orderedSources(mod.MetadataSources), extras...) {
		if err := ctx.Err(); err != nil {
			return doc, statusFailed, res, hardError(doc, err)
		}
		sr := runSource(ctx, resolve, src, mod, base, doc, nil) // sync path: no gate (unpaced)
		res.Stages++
		res.Warnings = append(res.Warnings, sr.warnings...)
		switch sr.kind {
		case outcomeSucceeded:
			if !begun { // first engaging source begins enrichment (new -> pending)
				status = advance(status, evBegin)
				begun = true
			} else if status == statusParsed { // a later source re-enters in-flight (parsed -> pending)
				status = advance(status, evBegin)
			}
			status = advance(status, evParsed) // pending -> parsed
			applyContribution(doc, sr)
			succeeded++
		case outcomeFailed:
			if !begun { // enrichment began, then this source failed (new -> pending); no further advance
				status = advance(status, evBegin)
				begun = true
			}
			failed++ // furthest-valid preserved: a failure never regresses the state
		}
		appendStage(doc, sr, status)
	}
	if begun && succeeded > 0 && failed == 0 {
		status = advance(status, evEnriched) // parsed -> enriched (run completed, all engaging sources ok)
	}
	res.Succeeded = succeeded
	return doc, status, res, nil
}

// orderedSources returns the bindings sorted by Priority ascending, stable so
// config order is the deterministic tiebreak (INV-serial-priority). The slice is
// copied so the module's config is not mutated.
func orderedSources(bindings []module.MetadataSourceBinding) []module.MetadataSourceBinding {
	out := make([]module.MetadataSourceBinding, len(bindings))
	copy(out, bindings)
	sort.SliceStable(out, func(i, j int) bool { return out[i].Priority < out[j].Priority })
	return out
}

// defaultExtraCapability is the capability id an element-attached plugin is
// resolved under when the module chain does not declare it — the same id every
// seeded metadata_source binding carries.
const defaultExtraCapability = "default"

// resolveExtraSources maps element-attached plugin ids (the item_parsers
// attachment order, element-pages D-3/D-4) onto source bindings. A plugin the
// module chain declares keeps its DECLARED binding — its AuthMode is the D-Q1
// truth (a CLIENT-locked attachment must stay unqueueable in the async queue).
// An undeclared plugin is a local metadata source: enabled, default capability,
// empty auth_mode (the anitomy case — D-4). Attachment order is preserved; a
// chain-declared id is kept too, so callers that DERIVE work see the same D-Q1
// facts the chain derivation saw.
func resolveExtraSources(mod module.Module, attached []string) []module.MetadataSourceBinding {
	if len(attached) == 0 {
		return nil
	}
	declared := make(map[string]module.MetadataSourceBinding, len(mod.MetadataSources))
	for _, src := range mod.MetadataSources {
		declared[src.PluginID] = src
	}
	out := make([]module.MetadataSourceBinding, 0, len(attached))
	for _, id := range attached {
		if src, ok := declared[id]; ok {
			out = append(out, src)
			continue
		}
		out = append(out, module.MetadataSourceBinding{
			PluginID:     id,
			CapabilityID: defaultExtraCapability,
			Enabled:      true,
		})
	}
	return out
}

// runExtras narrows resolveExtraSources to the bindings a RUN may execute: a
// chain-declared plugin is dropped because the chain already drives it (the
// queue dispatch and the sync Enrich must not run a source twice). Derivation
// keeps the full resolution instead — it must observe a declared CLIENT
// AuthMode to hold the D-Q1 lock on attached chain sources.
func runExtras(mod module.Module, attached []string) []module.MetadataSourceBinding {
	resolved := resolveExtraSources(mod, attached)
	chain := make(map[string]struct{}, len(mod.MetadataSources))
	for _, src := range mod.MetadataSources {
		chain[src.PluginID] = struct{}{}
	}
	out := resolved[:0]
	for _, src := range resolved {
		if _, ok := chain[src.PluginID]; ok {
			continue
		}
		out = append(out, src)
	}
	return out
}

// advance applies a transition, returning the next status or the current one if
// the transition is illegal (defensive — the orchestrator only emits legal ones).
func advance(status string, ev enrichEvent) string {
	if next, err := nextState(status, ev); err == nil {
		return next
	}
	return status
}

// appendStage records one per-source progress entry in _stages (the V5-hybrid
// progress map). advancedTo is the item status after this source ran.
func appendStage(doc map[string]any, sr sourceResult, advancedTo string) {
	stage := map[string]any{
		"stage":       "metadata_source",
		"plugin_id":   sr.pluginID,
		"status":      stageStatus(sr.kind),
		"advanced_to": advancedTo,
		"started_at":  sr.startedAt,
		"finished_at": sr.finishedAt,
	}
	if sr.errMsg != "" {
		stage["error"] = sr.errMsg
	}
	existing, _ := doc["_stages"].([]map[string]any)
	doc["_stages"] = append(existing, stage)
}

// applyContribution commits one source's validated namespace + provenance/_view
// entries to the document, and lands the source's resolved_ids claim in
// doc.identifiers (the identity anchor, enrichment D-4 — a CORE-side write
// OUTSIDE namespace validation, which polices only the plugin's Merge output).
// Called only on success (isolation: a failing source commits nothing).
func applyContribution(doc map[string]any, sr sourceResult) {
	if len(sr.resolvedIDs) > 0 {
		ids, _ := doc["identifiers"].(map[string]any)
		if ids == nil {
			ids = map[string]any{}
		}
		for k, v := range sr.resolvedIDs {
			ids[k] = v
		}
		doc["identifiers"] = ids
	}
	if sr.namespace != nil {
		sources, _ := doc["sources"].(map[string]any)
		if sources == nil {
			sources = map[string]any{}
		}
		sources[sr.pluginID] = sr.namespace
		doc["sources"] = sources
	}
	prov, _ := doc["_provenance"].(map[string]any)
	if prov == nil {
		prov = map[string]any{}
	}
	for field, p := range sr.provenance {
		prov[field] = p
	}
	doc["_provenance"] = prov
	view, _ := doc["_view"].(map[string]any)
	if view == nil {
		view = map[string]any{}
	}
	for field, v := range sr.view {
		view[field] = v
	}
	doc["_view"] = view
}

func stageStatus(k outcomeKind) string {
	switch k {
	case outcomeSucceeded:
		return "ok"
	case outcomeFailed:
		return "failed"
	case outcomeUnavailable:
		return "unavailable"
	default:
		return "skipped"
	}
}

// hardError stamps the _error record (Phase A records; Phase B does failed->pending
// retry) and returns the hard-fail cause for Enrich to propagate.
func hardError(doc map[string]any, err error) error {
	doc["_error"] = map[string]any{
		"stage":     "enrich",
		"code":      "cancelled",
		"message":   err.Error(),
		"retryable": true,
	}
	return fmt.Errorf("enrich: %w", err)
}
